import { getCanvassingAppList } from '~/client';
import type { CanvassingAppSelectorResponse } from '~/client';

export const useSelectorCanvassingAppList = defineQuery(() => {
  const { data, isLoading, error } = useQuery({
    key: () => ['selector-canvassing-app-list'],
    query: (): Promise<CanvassingAppSelectorResponse> => getCanvassingAppList({ composable: '$fetch' }),
  });

  return {
    canvassingApps: computed(() => data.value?.items ?? []),
    isLoading,
    error,
  };
});
